using LAC.Domain;
using Microsoft.EntityFrameworkCore;
using System.Text.Json;
namespace LAC.Infrastructure;
public sealed class LacDbContext(DbContextOptions<LacDbContext> options) : DbContext(options) {
 public DbSet<District> Districts => Set<District>(); public DbSet<SubDivision> SubDivisions => Set<SubDivision>(); public DbSet<Village> Villages => Set<Village>(); public DbSet<Khasra> Khasras => Set<Khasra>(); public DbSet<AcquisitionProject> AcquisitionProjects => Set<AcquisitionProject>(); public DbSet<Notification> Notifications => Set<Notification>(); public DbSet<Award> Awards => Set<Award>(); public DbSet<VillageLR> VillageLRs => Set<VillageLR>(); public DbSet<LREntry> LREntries => Set<LREntry>(); public DbSet<Document> Documents => Set<Document>(); public DbSet<DocumentVillage> DocumentVillages => Set<DocumentVillage>(); public DbSet<DocumentKhasra> DocumentKhasras => Set<DocumentKhasra>(); public DbSet<DocumentAward> DocumentAwards => Set<DocumentAward>(); public DbSet<DocumentNotification> DocumentNotifications => Set<DocumentNotification>(); public DbSet<DocumentVillageLR> DocumentVillageLRs => Set<DocumentVillageLR>(); public DbSet<AuditLog> AuditLogs => Set<AuditLog>();
 protected override void OnModelCreating(ModelBuilder b) { base.OnModelCreating(b); foreach(var e in b.Model.GetEntityTypes().Where(x=>typeof(OfficialRecord).IsAssignableFrom(x.ClrType))) b.Entity(e.ClrType).Property("RecordStatus").HasConversion<string>();
  b.Entity<District>().HasIndex(x=>x.Name).IsUnique(); b.Entity<SubDivision>().HasIndex(x=>new{x.DistrictId,x.Name}).IsUnique(); b.Entity<Village>().HasIndex(x=>new{x.SubDivisionId,x.Name}).IsUnique(); b.Entity<Khasra>().HasIndex(x=>new{x.VillageId,x.NormalizedNumber}).IsUnique(); b.Entity<Khasra>().Property(x=>x.TotalArea).HasPrecision(18,4);
  b.Entity<Notification>().HasIndex(x=>new{x.SectionType,x.NotificationNumber}).IsUnique(); b.Entity<Award>().HasIndex(x=>x.AwardNumber).IsUnique(); b.Entity<NotificationKhasra>().HasIndex(x=>new{x.NotificationId,x.KhasraId}).IsUnique(); b.Entity<AwardKhasra>().HasIndex(x=>new{x.AwardId,x.KhasraId}).IsUnique(); b.Entity<VillageLR>().HasIndex(x=>x.VillageId); b.Entity<LREntry>().HasIndex(x=>x.VillageLRId); b.Entity<LREntry>().Property(x=>x.Revision).IsConcurrencyToken().HasDefaultValue(0); b.Entity<LREntry>().HasOne(x=>x.Section4Notification).WithMany().HasForeignKey(x=>x.Section4NotificationId); b.Entity<LREntry>().HasOne(x=>x.Section6Notification).WithMany().HasForeignKey(x=>x.Section6NotificationId); b.Entity<LREntry>().HasOne(x=>x.Award).WithMany().HasForeignKey(x=>x.AwardId);
  b.Entity<DocumentVillage>().HasIndex(x=>new{x.DocumentId,x.VillageId}).IsUnique(); b.Entity<DocumentKhasra>().HasIndex(x=>new{x.DocumentId,x.KhasraId}).IsUnique(); b.Entity<DocumentAward>().HasIndex(x=>new{x.DocumentId,x.AwardId}).IsUnique(); b.Entity<DocumentNotification>().HasIndex(x=>new{x.DocumentId,x.NotificationId}).IsUnique(); b.Entity<DocumentVillageLR>().HasIndex(x=>new{x.DocumentId,x.VillageLRId}).IsUnique();
  b.Entity<NotificationKhasra>().Property(x=>x.NotifiedArea).HasPrecision(18,4); b.Entity<AwardKhasra>().Property(x=>x.AcquiredArea).HasPrecision(18,4); b.Entity<LREntry>().Property(x=>x.ParsedArea).HasPrecision(18,4); b.Entity<LREntry>().Property(x=>x.VerificationStatus).HasConversion<string>();
  foreach(var foreignKey in b.Model.GetEntityTypes().SelectMany(entity=>entity.GetForeignKeys())) foreignKey.DeleteBehavior=DeleteBehavior.Restrict;
 }
 public override async Task<int> SaveChangesAsync(CancellationToken ct=default) { var additions=ChangeTracker.Entries<Khasra>().Where(e=>e.State==EntityState.Added).Select(e=>e.Entity).ToList(); foreach(var khasra in additions) { var duplicateInRequest=additions.Any(x=>x!=khasra&&x.VillageId==khasra.VillageId&&x.NormalizedNumber==khasra.NormalizedNumber); var duplicateInStore=await Khasras.AnyAsync(x=>x.VillageId==khasra.VillageId&&x.NormalizedNumber==khasra.NormalizedNumber,ct); if(duplicateInRequest||duplicateInStore) throw new DbUpdateException("A Khasra with this normalized number already exists in the village."); }
  var now=DateTimeOffset.UtcNow; var changes=ChangeTracker.Entries().Where(e=>e.Entity is not AuditLog&&e.State is EntityState.Added or EntityState.Modified or EntityState.Deleted).ToList(); foreach(var entry in changes.Where(e=>e.State==EntityState.Deleted&&e.Entity is OfficialRecord)) { ((OfficialRecord)entry.Entity).RecordStatus=RecordStatus.Archived; entry.State=EntityState.Modified; } foreach(var e in ChangeTracker.Entries<OfficialRecord>()) { if(e.State==EntityState.Added) e.Entity.CreatedAt=now; if(e.State is EntityState.Added or EntityState.Modified) e.Entity.UpdatedAt=now; }
  foreach(var entry in changes) { var fields=entry.Properties.Where(p=>!p.Metadata.IsPrimaryKey()).ToDictionary(p=>p.Metadata.Name,p=>p.CurrentValue); AuditLogs.Add(new AuditLog { EntityType=entry.Metadata.ClrType.Name, EntityId=(Guid?)entry.Properties.FirstOrDefault(p=>p.Metadata.IsPrimaryKey())?.CurrentValue??Guid.Empty, Action=entry.State==EntityState.Added?"Created":entry.State==EntityState.Deleted?"Deleted":entry.Entity is OfficialRecord o&&o.RecordStatus==RecordStatus.Archived?"Archived":"Updated", ChangedAt=now, OldValues=entry.State==EntityState.Added?null:JsonSerializer.Serialize(entry.Properties.Where(p=>!p.Metadata.IsPrimaryKey()).ToDictionary(p=>p.Metadata.Name,p=>p.OriginalValue)), NewValues=entry.State==EntityState.Deleted?null:JsonSerializer.Serialize(fields) }); }
  return await base.SaveChangesAsync(ct); }
}
